; >S:LEVEL-INCREASE; PUT"LEVEL-INCREASE";;;; A CALL TO THIS ROUTINE SETS UP; ALL THE VARAIBLES AFFECTED BY; 'LEVEL';SETLVL;LDX LEVEL;LDA LVALMV,XSTA ALMVET;; ALIEN MOVE TEMPO;LDA LVNOKL,XSTA KILHEX;; NO. TO KILL (HEX);LDA LVNOKK,XSTA KILDEC;; NO. TO KILL (DEC);RTS;;------------------------;LVALMV;.BYTE 20,16,12,8,4;LVNOKL;.BYTE 10,15,20,25,30;LVNOKK;.BYTE $11,$16,$21,$26,$31;;------------------------;UPLEVL;; A CALL TO THIS UPS THE LEVEL; AND PRINTS A MESSAGE;INC LEVELLDA LEVELCMP #5BNE MLOK;LDA #4STA LEVEL;MLOK;; LEVEL NEVER > 4;JSR CLSWIN;LDX #<LVLOVRLDY #>LVLOVRJSR PWINT;JSR CLSSNDJSR CLSSNDJSR CLSSND;JMP PLAY;;-------------------;LVLOVR;.BYTE 8,8,$76,86,72,106,72,86,32,68,92,88,94,86,72,102,72,70,40,0.BYTE 8,9,$66,87,73,107,73,87,32,69,93,89,95,87,73,103,73,71,41,0;; LEVEL COMPLETED;.BYTE 9,12,$75,90,92,108,32,94,86,64,112,32,102,78,80,100,0.BYTE 9,13,$65,91,93,109,32,95,87,65,113,32,103,79,81,101,0;; NOW PLAY THIS;.BYTE $FF;;.END